// This function is a placeholder for a serverless function or an external service
// that handles form submission and sends an email.
// Direct SMTP from a client-side application is insecure and not reliable.
// The user MUST replace the `FORM_SUBMISSION_URL` with a real endpoint,
// such as a Formspree, Netlify Forms, or a custom serverless function.

const FORM_SUBMISSION_URL = "https://formspree.io/f/mjkzekwk"; // User's Formspree endpoint

export interface ContactFormData {
  name: string;
  email: string;
  company: string;
  description: string;
}

export async function sendEmail(formData: ContactFormData): Promise<boolean> {
  // Check if the user has replaced the placeholder URL
  if (FORM_SUBMISSION_URL === "YOUR_FORM_SUBMISSION_ENDPOINT_HERE") {
    console.error("FORM_SUBMISSION_URL is a placeholder. Please replace it with a real endpoint (e.g., Formspree or a serverless function) to enable email sending.");
    // Simulate success for development purposes
    return true;
  }

  try {
    const response = await fetch(FORM_SUBMISSION_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json",
      },
      body: JSON.stringify(formData),
    });

    if (response.ok) {
      console.log("Email sent successfully (via external service).");
      return true;
    } else {
      // Log the error response from the external service
      const errorData = await response.json();
      console.error("Email sending failed:", response.status, errorData);
      return false;
    }
  } catch (error) {
    console.error("Network or submission error:", error);
    return false;
  }
}

// Helper function to generate the email body for the user's reference
export function generateEmailBody(formData: ContactFormData): string {
  return `
    New Contact Form Submission:

    Name: ${formData.name}
    Email: ${formData.email}
    Company: ${formData.company || "N/A"}
    Message:
    ---
    ${formData.description}
    ---
  `;
}
